132	// discoverAndRegister contains the shared scanning logic for external agent discovery.
133	func discoverAndRegister(ctx context.Context) {
134		// As above: `ctx` remains the caller's, the derived timeout is named.
135		discoveryCtx, cancel := context.WithTimeout(ctx, discoveryTimeout)
136		defer cancel()
137	
138		for _, ref := range WalkExternalBinaries(ctx) {
139			if discoveryCanceled(ctx, discoveryCtx) {
140				logging.Debug(ctx, "external agent discovery timed out")
141				return
142			}
143			if _, err := registerExternalAgent(discoveryCtx, ref.BinaryPath, ref.Name); err != nil {
144				logging.Debug(ctx, "skipping external agent (registration failed)",
145					slog.String("binary", ref.BinaryPath),
146					slog.String("agent", string(ref.Name)),
147					slog.String("error", err.Error()))
148				continue
149			}
150		}
151	}
152	
153	// ExternalRef identifies an external agent binary found on $PATH by filename
154	// alone — no "info" subcommand is executed to produce it. Name is derived from
155	// the "entire-agent-<name>" filename; BinaryPath is the resolved path.
156	type ExternalRef struct {
157		Name       types.AgentName
158		BinaryPath string
159	}
160	
161	// WalkExternalBinaries scans $PATH for "entire-agent-*" executables and returns
162	// one ExternalRef per distinct agent name WITHOUT executing any binary. Names
163	// conflicting with an already-registered (built-in) agent are skipped, as are
164	// directories and non-executable files. Deduplicated by binary filename and by
165	// derived name (first match on $PATH wins), returned in sorted name order.
166	//
167	// This is the cheap discovery path for read-only listings: the caller learns
168	// every external's name and location for roughly one $PATH glob (~15ms for a
169	// large PATH), instead of paying an "info" exec per plugin (~100ms+ each).
170	func WalkExternalBinaries(ctx context.Context) []ExternalRef {
171		discoveryCtx, cancel := context.WithTimeout(ctx, discoveryTimeout)
172		defer cancel()
173	
174		pathEnv := os.Getenv("PATH")
175		if pathEnv == "" {
176			return nil
177		}
178	
179		// Collect already-registered names to avoid conflicts with built-ins.
180		registered := make(map[types.AgentName]bool)
181		for _, name := range agent.List() {
182			registered[name] = true
183		}
184	
185		seenBinary := make(map[string]bool)        // dedup by filename across PATH dirs
186		seenName := make(map[types.AgentName]bool) // dedup exe-ext variants of one name
187		var refs []ExternalRef
188		for _, dir := range filepath.SplitList(pathEnv) {
189			if discoveryCanceled(ctx, discoveryCtx) {
190				logging.Debug(ctx, "external agent discovery timed out")
191				break
192			}
193	
194			matches, err := filepath.Glob(filepath.Join(dir, binaryPrefix+"*"))
195			if err != nil {
196				continue // skip unreadable directories
197			}
198			for _, binPath := range matches {
199				base := filepath.Base(binPath)
200				if seenBinary[base] {
201					continue
202				}
203				seenBinary[base] = true
204	
205				// Strip Windows executable extensions (.exe, .bat) before deriving agent name.
206				// On Unix, binaries have no extension, so this is a no-op.
207				cleanName := StripExeExt(base)
208				agentName := types.AgentName(strings.TrimPrefix(cleanName, binaryPrefix))
209				if registered[agentName] {
210					logging.Debug(ctx, "skipping external agent (name conflict with built-in)",
211						slog.String("binary", base),
212						slog.String("agent", string(agentName)))
213					continue
214				}
215				if seenName[agentName] {
216					continue
217				}
218				if !isExecutableFile(binPath) {
219					continue
220				}
221				seenName[agentName] = true
222				refs = append(refs, ExternalRef{Name: agentName, BinaryPath: binPath})
223			}
224		}
225	
226		slices.SortFunc(refs, func(a, b ExternalRef) int {
227			return strings.Compare(string(a.Name), string(b.Name))
228		})
229		return refs
230	}
231	
232	// isExecutableFile reports whether binPath is a regular, executable file. On
233	// Windows the execute bit is not meaningful, so only the not-a-directory check
234	// applies. Mirrors the validity checks in registerExternalAgent, but stats only
235	// — it never executes the binary.
236	func isExecutableFile(binPath string) bool {
237		finfo, err := statExternalAgent(binPath)
238		if err != nil || finfo.IsDir() {
239			return false
240		}
241		if runtime.GOOS != osWindows && finfo.Mode()&0o111 == 0 {
242			return false
243		}
244		return true
245	}
